"""The shell shims that stand in for the old scripts: `slots shims install`."""
from __future__ import annotations

import os
import shlex
import shutil
import sys
import time
from pathlib import Path

HEADER = """\
# Generated by `slots shims install` ({when}). The old script's interface, now backed by slots:
# same arguments, output and exit codes. Limits come from the slots config, not from this file.
"""

AGENT_SLOT = """\
#!/usr/bin/env bash
{header}#
#   agent-slot.sh acquire <ticket> [--wait]   # take a free agent slot; --wait waits in line (no polling)
#   agent-slot.sh release <ticket>            # give it back after your processes are stopped
#   agent-slot.sh status                      # who holds what, since when
#   agent-slot.sh e2e-acquire <ticket> [--wait] | e2e-release <ticket>
exec {slots} compat agent-slot "$@"
"""

SLOT_SH = """\
#!/usr/bin/env bash
{header}#
#   slot.sh [--label <who>] -- <command...>    # run a heavy command in a machine-wide test slot
set -euo pipefail

label="${{USER:-someone}} $$"
while [[ $# -gt 0 ]]; do
  case "$1" in
    --label) label="$2"; shift 2 ;;
    --) shift; break ;;
    *) echo "usage: slot.sh [--label <who>] -- <command...>" >&2; exit 2 ;;
  esac
done
[[ $# -gt 0 ]] || {{ echo "usage: slot.sh [--label <who>] -- <command...>" >&2; exit 2; }}

exec {slots} compat run-in-slot "$label" -- "$@"
"""

LIB_SLOT = """\
# Machine-wide test slots and exclusive locks (sourced by ta-e2e.sh and slot.sh).
{header}
HARNESS_ROOT="$(cd "$(dirname "${{BASH_SOURCE[0]}}")/.." && pwd)"
TA_SLOT_DIR="${{TA_SLOT_DIR:-$HARNESS_ROOT/.locks}}"   # kept for scripts that read it; slots doesn't use it
LOCK_BUSY=75
_slots() {{ {slots} "$@"; }}
TA_SLOT_COUNT="$(_slots compat slot-count 2>/dev/null || echo 0)"

# Who holds which slot: "<label> (pid N, since HH:MM:SSZ)", joined with ";".
slot_holders() {{ _slots compat slot-holders; }}

# run_in_slot <label> <command...>: runs the command in a free test slot and returns its exit code.
run_in_slot() {{ local label="$1"; shift; _slots compat run-in-slot "$label" -- "$@"; }}

# run_exclusive <lock> <what> <label> <command...>: runs the command holding one exclusive lock,
# with TA_EXCLUSIVE_LOCK=<lock> set, and returns its exit code.
run_exclusive() {{ local name="$1" what="$2" label="$3"; shift 3; _slots compat run-exclusive "$name" "$what" "$label" -- "$@"; }}

# next_employee_lock <email>: the per-employee lock name (same as lib/env.ts nextEmployeeLock).
next_employee_lock() {{ _slots compat employee-lock "$1"; }}
"""

SHIMS = {"agent-slot.sh": AGENT_SLOT, "slot.sh": SLOT_SH, "lib-slot.sh": LIB_SLOT}


def slots_command(config_path: Path | None, use_path: bool = True) -> str:
    """How a shim runs slots: the installed `slots` if it's on PATH, else this interpreter; with the
    config that was in use at install time, unless $SLOTS_CONFIG says otherwise when it runs."""
    exe = shutil.which("slots") if use_path else None
    if exe:
        base = shlex.quote(exe)
    else:
        src = str(Path(__file__).resolve().parent.parent)
        base = (f'env PYTHONPATH={shlex.quote(src)}"${{PYTHONPATH:+:$PYTHONPATH}}" '
                f"{shlex.quote(sys.executable)} -m slots")
    if config_path:
        return f'{base} --config "${{SLOTS_CONFIG:-{config_path.resolve()}}}"'
    return base


def install(directory: Path, config_path: Path | None, *, only: list[str] | None = None,
            force: bool = False, use_path: bool = True) -> list[str]:
    """Write the shims. An existing file is kept as <name>.orig-<timestamp> (only with force)."""
    directory.mkdir(parents=True, exist_ok=True)
    names = only or list(SHIMS)
    unknown = [n for n in names if n not in SHIMS]
    if unknown:
        raise ValueError(f"unknown shim(s): {', '.join(unknown)} (known: {', '.join(SHIMS)})")
    report, slots = [], slots_command(config_path, use_path)
    header = HEADER.format(when=time.strftime("%Y-%m-%d"))
    for name in names:
        target = directory / name
        text = SHIMS[name].format(header=header, slots=slots)
        if target.exists():
            if target.read_text() == text:
                report.append(f"unchanged {target}")
                continue
            if not force:
                report.append(f"skipped   {target} (exists; --force keeps it as {name}.orig-<time> and replaces it)")
                continue
            backup = target.with_name(f"{name}.orig-{time.strftime('%Y%m%d%H%M%S')}")
            os.replace(target, backup)
            report.append(f"kept      {backup}")
        target.write_text(text)
        target.chmod(0o755 if name != "lib-slot.sh" else 0o644)
        report.append(f"wrote     {target}")
    return report
